import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AttendanceState, AttendanceStats } from '../types';
import { calculateStats } from '../utils/calculations';

export const Dashboard: React.FC = () => {
  const [state, setState] = useState<AttendanceState>({
    totalClasses: 0,
    absentClasses: 0,
    examDate: '',
    holidays: []
  });

  const [stats, setStats] = useState<AttendanceStats | null>(null);

  useEffect(() => {
    setStats(calculateStats(state));
  }, [state]);

  const handleChange = (field: keyof AttendanceState, value: any) => {
    setState(prev => ({ ...prev, [field]: value }));
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { y: 0, opacity: 1 }
  };

  return (
    <div className="min-h-screen py-20 px-4 md:px-12 max-w-7xl mx-auto">
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="grid grid-cols-1 lg:grid-cols-2 gap-12"
      >
        {/* Controls Section */}
        <motion.div variants={itemVariants} className="space-y-8">
          <div className="glass-panel p-8 rounded-3xl neon-glow relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-32 h-32 bg-cyan-500/10 rounded-full blur-3xl transform translate-x-16 -translate-y-16 group-hover:bg-cyan-500/20 transition-all duration-500"></div>

            <h2 className="text-3xl font-bold mb-8 text-white">Input Data</h2>

            <div className="space-y-6">
              {/* Total Classes */}
              <div className="space-y-2">
                <label className="text-slate-400 text-sm uppercase tracking-wider font-semibold">Total Classes Held</label>
                <input
                  type="number"
                  min="0"
                  value={state.totalClasses || ''}
                  onChange={(e) => handleChange('totalClasses', parseInt(e.target.value) || 0)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-cyan-500 transition-colors text-lg"
                  placeholder="e.g. 120"
                />
              </div>

              {/* Absent Classes */}
              <div className="space-y-2">
                <label className="text-slate-400 text-sm uppercase tracking-wider font-semibold">Classes Absent</label>
                <input
                  type="number"
                  min="0"
                  value={state.absentClasses || ''}
                  onChange={(e) => handleChange('absentClasses', parseInt(e.target.value) || 0)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-red-500/50 transition-colors text-lg"
                  placeholder="e.g. 25"
                />
              </div>

              {/* Exam Date */}
              <div className="space-y-2">
                <label className="text-slate-400 text-sm uppercase tracking-wider font-semibold">Exam Start Date</label>
                <input
                  type="date"
                  value={state.examDate}
                  onChange={(e) => handleChange('examDate', e.target.value)}
                  className="w-full bg-slate-900/50 border border-slate-700 rounded-xl px-4 py-4 text-white focus:outline-none focus:border-cyan-500 transition-colors text-lg [color-scheme:dark]"
                />
              </div>

               {/* Holidays */}
               <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="text-slate-400 text-sm uppercase tracking-wider font-semibold">Holidays (Optional)</label>
                    <span className="text-xs text-slate-500">Add dates excluded from class</span>
                  </div>
                  <div className="flex gap-2">
                    <input type="date" id="holidayInput" className="bg-slate-900/50 border border-slate-700 rounded-lg px-3 py-2 text-white text-sm flex-grow [color-scheme:dark]" />
                    <button 
                        onClick={() => {
                            const input = document.getElementById('holidayInput') as HTMLInputElement;
                            if (input.value && !state.holidays.includes(input.value)) {
                                handleChange('holidays', [...state.holidays, input.value]);
                                input.value = '';
                            }
                        }}
                        className="px-4 py-2 bg-cyan-600 hover:bg-cyan-500 text-white rounded-lg text-sm font-bold transition-colors"
                    >
                        Add
                    </button>
                  </div>
                  {state.holidays.length > 0 && (
                      <div className="flex flex-wrap gap-2 mt-2">
                          {state.holidays.map(h => (
                              <span key={h} className="bg-slate-800 text-slate-300 text-xs px-2 py-1 rounded-md flex items-center gap-1">
                                  {h}
                                  <button onClick={() => handleChange('holidays', state.holidays.filter(d => d !== h))} className="text-red-400 hover:text-red-300">×</button>
                              </span>
                          ))}
                      </div>
                  )}
               </div>
            </div>
          </div>
        </motion.div>

        {/* Analytics Section */}
        <motion.div variants={itemVariants} className="space-y-6">

          {/* Main Percentage Card */}
          <div className="glass-panel p-8 rounded-3xl relative overflow-hidden flex flex-col items-center justify-center text-center h-full min-h-[400px]">
            <motion.div 
              className={`absolute -inset-16 rounded-full blur-3xl opacity-50 transition-colors duration-1000 ${stats?.isSafe ? 'bg-cyan-900' : 'bg-red-900'}`}
              animate={{ scale: [1, 1.1, 1], rotate: [0, 90, 0] }}
              transition={{ duration: 20, repeat: Infinity, ease: 'easeInOut' }}
            />

            <h3 className="text-slate-400 font-medium mb-4 uppercase tracking-widest text-sm z-10">Current Attendance</h3>
            <div className="relative z-10">
                <svg className="w-64 h-64 transform -rotate-90" viewBox="0 0 256 256">
                    <defs>
                      <filter id="glow-cyan" x="-50%" y="-50%" width="200%" height="200%">
                        <feDropShadow dx="0" dy="0" stdDeviation="4.5" floodColor="#22d3ee" />
                      </filter>
                      <filter id="glow-red" x="-50%" y="-50%" width="200%" height="200%">
                        <feDropShadow dx="0" dy="0" stdDeviation="4.5" floodColor="#f87171" />
                      </filter>
                    </defs>
                    <circle cx="128" cy="128" r="120" stroke="#1e293b" strokeWidth="12" fill="transparent" />
                    <circle cx="128" cy="128" r="100" stroke="#1e293b" strokeWidth="1" fill="transparent" strokeDasharray="2 8" />

                    <motion.circle 
                        cx="128" cy="128" r="120" 
                        stroke={stats?.isSafe ? "#22d3ee" : "#f87171"} 
                        strokeWidth="12" 
                        fill="transparent"
                        strokeDasharray={2 * Math.PI * 120}
                        strokeLinecap="round"
                        initial={{ strokeDashoffset: 2 * Math.PI * 120 }}
                        animate={{ strokeDashoffset: 2 * Math.PI * 120 * (1 - (stats?.currentPercentage || 0) / 100) }}
                        transition={{ duration: 1.5, type: "spring", stiffness: 50, damping: 15 }}
                        style={{ filter: `url(#glow-${stats?.isSafe ? 'cyan' : 'red'})` }}
                    />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <AnimatePresence mode="wait">
                        <motion.span 
                            className="text-7xl font-bold text-white tracking-tighter bg-clip-text text-transparent bg-gradient-to-b from-white to-slate-400 drop-shadow-lg"
                            key={stats?.currentPercentage.toFixed(1)}
                            initial={{ opacity: 0, y: -20 }}
                            animate={{ opacity: 1, y: 0 }}
                            exit={{ opacity: 0, y: 20 }}
                            transition={{ duration: 0.3 }}
                        >
                            {stats?.currentPercentage.toFixed(1)}%
                        </motion.span>
                    </AnimatePresence>

                    <AnimatePresence mode="wait">
                      <motion.span
                        key={stats?.isSafe ? 'safe' : 'danger'}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.8 }}
                        transition={{ duration: 0.3 }}
                        className={`mt-2 px-4 py-1.5 rounded-full text-xs font-bold uppercase tracking-wider ${stats?.isSafe ? 'bg-cyan-500/20 text-cyan-300' : 'bg-red-500/20 text-red-300'} border ${stats?.isSafe ? 'border-cyan-500/30' : 'border-red-500/30'}`}
                      >
                          {stats?.isSafe ? 'Safe Zone' : 'Danger Zone'}
                      </motion.span>
                    </AnimatePresence>
                </div>
            </div>
          </div>
        </motion.div>

        {/* Stats Grid - Full Width */}
        <motion.div variants={itemVariants} className="col-span-1 lg:col-span-2 grid grid-cols-1 md:grid-cols-3 gap-6">

            {/* Safe to Bunk Card */}
            <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group min-h-[160px] flex flex-col justify-center">
                <div className="absolute inset-0 bg-gradient-to-br from-green-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-3">BUNKABLE POTENTIAL</h4>

                {stats?.hasExamDate ? (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-5xl font-bold text-white">
                            {stats?.bunkableClasses}
                        </span>
                        <span className="text-sm text-slate-500 mb-1 pb-1">classes</span>
                    </div>
                    <p className="text-sm text-slate-400 mt-2 font-medium">
                        Equivalent to <span className="text-cyan-400 font-bold">{stats?.bunkableDays} full days</span> of absence while staying safe.
                    </p>
                  </>
                ) : (
                  <p className="text-sm text-slate-500 italic mt-2 leading-relaxed">
                    Select a future exam date to calculate bunkability.
                  </p>
                )}
            </div>

            {/* Recovery Card (MUST ATTEND) */}
            <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group min-h-[160px] flex flex-col justify-center">
                <div className="absolute inset-0 bg-gradient-to-br from-purple-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-3">
                  {stats?.hasExamDate ? (stats?.isPossibleToReachTarget ? 'MUST ATTEND' : 'TARGET UNREACHABLE') : 'MUST ATTEND'}
                </h4>

                {!stats?.hasExamDate ? (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-5xl font-bold text-white">
                            {stats?.requiredClasses}
                        </span>
                        <span className="text-sm text-slate-500 mb-1 pb-1">classes</span>
                    </div>
                    <p className="text-sm text-slate-400 mt-2 font-medium">
                        Classes needed <span className="text-purple-400 font-bold">immediately</span> to reach 75%. (Exam date needed for long-term check)
                    </p>
                  </>
                ) : stats?.isPossibleToReachTarget ? (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-5xl font-bold text-white">
                            {stats?.requiredClasses}
                        </span>
                        <span className="text-sm text-slate-500 mb-1 pb-1">classes</span>
                    </div>
                    <p className="text-sm text-slate-400 mt-2 font-medium">
                        You need <span className="text-cyan-400 font-bold">{stats?.requiredDays} full days</span> of attendance to reach 75%.
                    </p>
                  </>
                ) : (
                  <>
                    <div className="flex items-end gap-2">
                        <span className="text-5xl font-bold text-red-400">
                            {stats?.maxAchievablePercentage.toFixed(1)}%
                        </span>
                        <span className="text-sm text-slate-500 mb-1 pb-1">max</span>
                    </div>
                    <p className="text-sm text-red-400 mt-2 font-medium">
                        Even with 100% attendance from now, you cannot hit 75% before the exam.
                    </p>
                  </>
                )}
            </div>

            {/* Tomorrow Projection */}
            <div className="glass-panel p-6 rounded-2xl relative overflow-hidden group min-h-[160px] flex flex-col justify-center">
                 <div className="absolute inset-0 bg-gradient-to-br from-orange-500/5 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                <h4 className="text-slate-400 text-sm font-bold uppercase tracking-wider mb-3">IF ABSENT TOMORROW</h4>
                <div className="flex items-end gap-2">
                    <span className={`text-5xl font-bold ${(stats?.tomorrowImpact || 0) < 75 ? 'text-red-400' : 'text-orange-300'}`}>
                        {stats?.tomorrowImpact.toFixed(1)}%
                    </span>
                </div>
                <p className="text-sm text-slate-400 mt-2">
                    Your percentage drops to this if you miss all 6 classes tomorrow.
                </p>
            </div>

        </motion.div>
      </motion.div>
    </div>
  );
};
